// Build script: `npm run build`
//
//   src/tools/*.jsx  ──esbuild──▶  assets/js/   (one file per tool + a shared React chunk)
//   src/styles.css   ──tailwind─▶  assets/css/app.css
//   @fontsource/*    ──copy─────▶  assets/fonts/ (self-hosted, no Google Fonts request)
//   src/site.js      ──render───▶  index.html + one HTML page per tool
//
// The generated files are committed, so GitHub Pages serves them as-is (no CI needed).

import { build } from 'esbuild';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { copyFileSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { TOOLS, renderIndex, renderTool } from './src/site.js';

const root = path.dirname(fileURLToPath(import.meta.url));
const r = (...p) => path.join(root, ...p);
const hash = (file) => createHash('sha256').update(readFileSync(file)).digest('hex').slice(0, 10);

// ── 1. Fonts ────────────────────────────────────────────────────────────────
const FONTS = [
  { pkg: '@fontsource/hind-siliguri', weights: [400, 500, 600, 700], subsets: ['bengali', 'latin'] },
  { pkg: '@fontsource/jetbrains-mono', weights: [400, 600], subsets: ['latin'] },
];
rmSync(r('assets/fonts'), { recursive: true, force: true });
mkdirSync(r('assets/fonts'), { recursive: true });
mkdirSync(r('src/generated'), { recursive: true });
let fontCss = '/* Generated by build.mjs from @fontsource packages. */\n';
for (const font of FONTS) {
  for (const weight of font.weights) {
    const css = readFileSync(r('node_modules', font.pkg, `${weight}.css`), 'utf8');
    for (const block of css.split('@font-face').slice(1)) {
      const file = block.match(/url\(\.\/files\/([^)]+\.woff2)\)/)?.[1];
      if (!file || !font.subsets.some((s) => file.includes(`-${s}-${weight}-`))) continue;
      const family = block.match(/font-family:\s*'([^']+)'/)[1];
      const range = block.match(/unicode-range:\s*([^;]+);/)[1];
      copyFileSync(r('node_modules', font.pkg, 'files', file), r('assets/fonts', file));
      fontCss += `@font-face{font-family:'${family}';font-style:normal;font-display:swap;font-weight:${weight};src:url(../fonts/${file}) format('woff2');unicode-range:${range}}\n`;
    }
  }
}
writeFileSync(r('src/generated/fonts.css'), fontCss);

// ── 2. CSS ──────────────────────────────────────────────────────────────────
execFileSync(
  process.execPath,
  [r('node_modules/tailwindcss/lib/cli.js'), '-c', r('tailwind.config.js'), '-i', r('src/styles.css'), '-o', r('assets/css/app.css'), '--minify'],
  { stdio: 'inherit', cwd: root },
);

// ── 3. JavaScript ───────────────────────────────────────────────────────────
rmSync(r('assets/js'), { recursive: true, force: true });
await build({
  entryPoints: Object.fromEntries(TOOLS.map((t) => [t.entry, r('src/tools', `${t.entry}.jsx`)])),
  outdir: r('assets/js'),
  bundle: true,
  splitting: true, // React lands in one shared chunk that the browser caches across pages
  format: 'esm',
  minify: true,
  jsx: 'automatic',
  target: ['es2020'],
  chunkNames: 'chunks/[name]-[hash]',
  define: { 'process.env.NODE_ENV': '"production"' },
  legalComments: 'eof',
  logLevel: 'warning',
});

// ── 4. HTML ─────────────────────────────────────────────────────────────────
const assets = {
  css: hash(r('assets/css/app.css')),
  js: Object.fromEntries(TOOLS.map((t) => [t.entry, hash(r('assets/js', `${t.entry}.js`))])),
};
writeFileSync(r('index.html'), renderIndex(assets));
for (const tool of TOOLS) writeFileSync(r(tool.file), renderTool(tool, assets));

console.log(`Built index.html + ${TOOLS.length} tool pages.`);
